  196: { "id_dec": 196, "save_bytes_le": null, "name_ja": "ミミズ", "name_en": "Earthworms", "reading": "みみず", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。扱いやすく 川魚に有効。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Easy to use, and effective in catching freshwater fish.", "source": "TS", "備考": "" },
  197: { "id_dec": 197, "save_bytes_le": null, "name_ja": "ゴカイ", "name_en": "Sandworms", "reading": "ごかい", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。幅広い海魚に有効な虫エサ。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Great for catching virtually any kind of saltwater fish.", "source": "TS", "備考": "" },
  198: { "id_dec": 198, "save_bytes_le": null, "name_ja": "オキアミ", "name_en": "Krill", "reading": "おきあみ", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。海魚を中心に珍しい物がかかる。", "description_en": "Fishing bait. Allows you to fish when near any body of water. A rare type that works extremely well for catching saltwater fish.", "source": "TS", "備考": "" },
  199: { "id_dec": 199, "save_bytes_le": null, "name_ja": "エビ", "name_en": "Shrimp", "reading": "えび", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。扱いの難しい大物狙いのエサ。", "description_en": "Fishing bait. Allows you to fish when near any body of water. A bit hard to use, but works wonders for catching large-scale fish.", "source": "TS", "備考": "" },
  200: { "id_dec": 200, "save_bytes_le": null, "name_ja": "小魚", "name_en": "Minnow", "reading": "こざかな", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。扱いの難しい大物狙いのエサ。", "description_en": "Fishing bait. Allows you to fish when near any body of water. A bit hard to use, but works wonders for catching large-scale fish.", "source": "TS", "備考": "" },
  201: { "id_dec": 201, "save_bytes_le": null, "name_ja": "疑似餌", "name_en": "Lure", "reading": "ぎじえ", "kind": 0, "max_stack": 10, "description_ja": "本物に似せた釣りのエサ。水場の近くで釣りを始めることができる。効果は平均的。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Designed to mimic the real deal, but is only average at best.", "source": "TS", "備考": "" },
  202: { "id_dec": 202, "save_bytes_le": null, "name_ja": "ねりエサ", "name_en": "Organic Bait", "reading": "ねりえさ", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。川魚に有効だが扱いが難しい。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Works great for catching freshwater fish, but is a bit hard to use.", "source": "TS", "備考": "" },
  203: { "id_dec": 203, "save_bytes_le": null, "name_ja": "もち", "name_en": "Mochi", "reading": "もち", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。魚以外の物がくっつきやすい。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Works surprisingly well for catching things other than fish.", "source": "TS", "備考": "" },
  204: { "id_dec": 204, "save_bytes_le": null, "name_ja": "力ミミズ", "name_en": "Super Earthworms", "reading": "ちからみみず", "kind": 0, "max_stack": 10, "description_ja": "釣りのエサ。水場の近くで釣りを始めることができる。ミミズよりも扱いづらい分 魅力は高い。", "description_en": "Fishing bait. Allows you to fish when near any body of water. Harder to handle than an ordinary earthworm, but fish seem to be enthralled by it.", "source": "TS", "備考": "" },
